using System.Threading.Tasks;
using Newtonsoft.Json.Linq;
using Octoshift.Models;
using OctoshiftCLI.Extensions;

namespace OctoshiftCLI.Services;

/// <summary>
/// Coordinates a safe end-to-end test of an Azure DevOps pipeline migration to GitHub.
/// The pipeline is temporarily rewired to the GitHub repo, a build is queued and monitored,
/// and the pipeline is then restored to its original Azure Repos configuration.
/// </summary>
public class PipelineTestService
{
    private readonly OctoLogger _log;
    private readonly AdoApi _adoApi;
    private readonly AdoPipelineTriggerService _pipelineTriggerService;

    private const int DefaultMonitorTimeoutMinutes = 30;

    public PipelineTestService(OctoLogger log, AdoApi adoApi, AdoPipelineTriggerService pipelineTriggerService)
    {
        _log = log;
        _adoApi = adoApi;
        _pipelineTriggerService = pipelineTriggerService;
    }

    public virtual async Task<PipelineTestResult> TestPipeline(PipelineTestArgs args)
    {
        if (args is null)
        {
            throw new ArgumentNullException(nameof(args));
        }

        var result = new PipelineTestResult
        {
            AdoOrg = args.AdoOrg,
            AdoTeamProject = args.AdoTeamProject,
            PipelineName = args.AdoPipeline,
            StartTime = DateTime.UtcNow
        };

        // Resolve the pipeline id if it wasn't supplied.
        var pipelineId = args.PipelineId ?? await _adoApi.GetPipelineId(args.AdoOrg, args.AdoTeamProject, args.AdoPipeline);
        result.PipelineId = pipelineId;

        // Retrieve the original pipeline info so we can rewire it and later restore it.
        var definitionUrl = $"/{args.AdoOrg.EscapeDataString()}/{args.AdoTeamProject.EscapeDataString()}/_apis/build/definitions/{pipelineId}?api-version=6.0";
        var originalDefinition = JObject.Parse(await _adoApi.GetAsync(definitionUrl));

        result.AdoRepoName = originalDefinition["repository"]?["name"]?.ToString();
        result.PipelineUrl = originalDefinition["_links"]?["web"]?["href"]?.ToString();

        var (defaultBranch, clean, checkoutSubmodules, triggers) = await _adoApi.GetPipeline(args.AdoOrg, args.AdoTeamProject, pipelineId);

        // Rewire the pipeline to point at the GitHub repo.
        await _pipelineTriggerService.RewirePipelineToGitHub(
            args.AdoOrg,
            args.AdoTeamProject,
            pipelineId,
            defaultBranch,
            clean,
            checkoutSubmodules,
            args.GithubOrg,
            args.GithubRepo,
            args.ServiceConnectionId,
            triggers,
            args.TargetApiUrl);

        result.RewiredSuccessfully = true;

        try
        {
            if (args.DryRun)
            {
                _log.LogInformation("Dry run enabled - skipping build queue and monitoring.");
            }
            else
            {
                // Queue a build against the rewired pipeline.
                var (buildId, buildUrl) = await QueueBuild(args.AdoOrg, args.AdoTeamProject, pipelineId);
                result.BuildId = buildId;
                result.BuildUrl = buildUrl;

                // Monitor the build until it completes or the timeout elapses.
                var timeout = args.MonitorTimeoutMinutes > 0 ? args.MonitorTimeoutMinutes : DefaultMonitorTimeoutMinutes;
                var (status, buildResult) = await MonitorBuild(args.AdoOrg, args.AdoTeamProject, buildId, timeout);
                result.Status = status;
                result.Result = buildResult;
            }
        }
        finally
        {
            // Always attempt to restore the pipeline to its original Azure Repos configuration.
            try
            {
                await RestorePipelineToAdoRepo(args.AdoOrg, args.AdoTeamProject, pipelineId, originalDefinition);
                result.RestoredSuccessfully = true;
            }
            catch (Exception ex)
            {
                result.RestoredSuccessfully = false;
                result.ErrorMessage = $"Failed to restore: {ex.Message}";
            }
        }

        result.EndTime = DateTime.UtcNow;

        return result;
    }

    private async Task<(int BuildId, string BuildUrl)> QueueBuild(string adoOrg, string adoTeamProject, int pipelineId)
    {
        var url = $"/{adoOrg.EscapeDataString()}/{adoTeamProject.EscapeDataString()}/_apis/build/builds?api-version=6.0";

        var payload = new
        {
            definition = new
            {
                id = pipelineId
            }
        };

        var response = JObject.Parse(await _adoApi.PostAsync(url, payload));

        var buildId = (int)response["id"];
        var buildUrl = response["_links"]?["web"]?["href"]?.ToString();

        _log.LogInformation($"Queued build {buildId} for pipeline {pipelineId}");

        return (buildId, buildUrl);
    }

    private async Task<(string Status, string Result)> MonitorBuild(string adoOrg, string adoTeamProject, int buildId, int timeoutMinutes)
    {
        var url = $"/{adoOrg.EscapeDataString()}/{adoTeamProject.EscapeDataString()}/_apis/build/builds/{buildId}?api-version=6.0";
        var deadline = DateTime.UtcNow.AddMinutes(timeoutMinutes);

        string status = null;
        string result = null;

        while (DateTime.UtcNow < deadline)
        {
            var response = JObject.Parse(await _adoApi.GetAsync(url));
            status = response["status"]?.ToString();
            result = response["result"]?.ToString();

            if (string.Equals(status, "completed", StringComparison.OrdinalIgnoreCase))
            {
                _log.LogInformation($"Build {buildId} completed with result: {result}");
                return (status, result);
            }

            await Task.Delay(TimeSpan.FromSeconds(10));
        }

        _log.LogWarning($"Build {buildId} did not complete within {timeoutMinutes} minute(s).");

        return (status, result);
    }

    private async Task RestorePipelineToAdoRepo(string adoOrg, string adoTeamProject, int pipelineId, JObject originalDefinition)
    {
        var url = $"/{adoOrg.EscapeDataString()}/{adoTeamProject.EscapeDataString()}/_apis/build/definitions/{pipelineId}?api-version=6.0";

        await _adoApi.PutAsync(url, originalDefinition.ToObject(typeof(object)));

        _log.LogInformation($"Restored pipeline {pipelineId} to its original Azure Repos configuration.");
    }
}
